    (error == NULL)) {
    if (body != NULL) {
        *body = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    if (recovered != NULL) {
        *recovered = (adcs_vec3_t){0.0, 0.0, 0.0};
    }
    if (error != NULL) {
        *error = INFINITY;
    }
    return ADCS_E_NULL;
}

